<button {{ $attributes->merge(['type' => 'submit', 'class' => 'inline-flex items-center px-4 py-2 border border-transparent rounded-md font-semibold text-xs uppercase tracking-widest focus:outline-none focus:ring-2 focus:ring-offset-2 transition ease-in-out duration-150']) }} style="background-color: var(--brand-color, #111827); color: var(--brand-foreground, #ffffff);" onmouseover="this.style.backgroundColor = getComputedStyle(this).getPropertyValue('--brand-hover-color') || '#0f172a';" onmouseout="this.style.backgroundColor = getComputedStyle(this).getPropertyValue('--brand-color') || '#111827';">
